// Types for sol-montecarlo-2380.json, schemaVersion 1.0.0.
// Generated by tools/colonization-sim.js with --export. Fan work set in the Star Trek universe; not official.
//
// A summary of many complete simulated histories (one per seed). The shop uses one run
// (sol-telecom-2380.json, seed 1701); this file shows where that run sits in the spread.

export interface MonteCarloSummary {
  schemaVersion: "1.0.0";
  run: {
    /** Seeds are firstSeed to firstSeed + runCount - 1. */
    firstSeed: number;
    runCount: number;
    /** The seed of the run in sol-telecom-2380.json. */
    canonicalSeed: number;
    startYear: number;
    endYear: number;
    /** The git commit of tools/colonization-sim.js that made this file. It must match the dataset's. */
    scriptCommit: string | null;
    generatedAt: string;
  };
  worlds: WorldSummary[];
  deadlines: DeadlineResult[];
  market: {
    companiesFounded: Spread;
    brandsTrading: Spread;
    companiesBought: Spread;
    /** Brands still trading, by company kind label. */
    brandsByKind: Record<string, Spread>;
  };
}

/** Median and the 10th and 90th percentile (nearest rank). */
export interface Spread {
  median: number | null;
  p10: number | null;
  p90: number | null;
}

export type Metric = "constellation" | "subspace" | "colonized" | "oneMillion" | "population";

export interface WorldSummary {
  id: string;
  name: string;
  metrics: Record<Metric, MetricSummary>;
}

export interface MetricSummary extends Spread {
  /** Share of runs in which the event happened (0 to 1). */
  shareOfRuns: number;
  /** One value per run in which it happened, ascending: a year, or people for "population". */
  samples: number[];
}

/** A canon deadline: the latest date canon allows, and how often the simulation met it. */
export interface DeadlineResult {
  world: string;
  event: "colonized" | "constellation" | "population";
  by: number;
  /** Population deadlines only. */
  atLeast?: number;
  source: string;
  /** Share of runs that met it (0 to 1). */
  shareMet: number;
  /** Median year (or population) the simulation produced. */
  medianResult: number | null;
}
